/// session-list: Sign out one or every other session
private struct SessionListExample0: View {
    @State private var sessions = [
        MonarchSession(
            id: "s-1",
            label: "Chrome on macOS",
            signedIn: Date(timeIntervalSinceNow: -30 * 3600),
            lastActive: Date(timeIntervalSinceNow: -0 * 3600),
            isCurrent: true
        ),
        MonarchSession(
            id: "s-2",
            label: "Safari on iPhone",
            kind: .mobile,
            detail: "Lisbon, Portugal",
            signedIn: Date(timeIntervalSinceNow: -200 * 3600),
            lastActive: Date(timeIntervalSinceNow: -3 * 3600)
        ),
        MonarchSession(
            id: "s-3",
            label: "Firefox on Linux",
            kind: .desktop,
            signedIn: Date(timeIntervalSinceNow: -500 * 3600),
            lastActive: Date(timeIntervalSinceNow: -72 * 3600)
        ),
    ]

    var body: some View {
        MonarchSessionList(
            sessions,
            footnote: "Apps already open on a device you sign out can stay signed in for a few minutes.",
            onSignOut: { id in
                // The app ends the session on the server.
                try await Task.sleep(for: .milliseconds(300))
                sessions.removeAll { $0.id == id }
            },
            onSignOutOthers: { ids in
                try await Task.sleep(for: .milliseconds(300))
                sessions.removeAll { ids.contains($0.id) }
            }
        )
    }
}

